export function resolveCheckoutImpl(flags: FlagClient): CheckoutImpl {
  // QA/dev override: ?checkout=svelte
  const override = new URLSearchParams(window.location.search).get('checkout');
  if (override === 'react' || override === 'svelte') return override;

  try {
    return flags.getVariant(FLAG_KEY, 'react'); // default to React
  } catch {
    return 'react';
  }
}
