import { resolveCheckoutImpl, type FlagClient } from './flag';

export interface CheckoutProps {
  cartId: string;
  // ...whatever the checkout needs
}

// Both implementations export the same contract
export type MountFn = (el: HTMLElement, props: CheckoutProps) => () => void; // returns unmount

export async function mountCheckout(
  el: HTMLElement,
  props: CheckoutProps,
  flags: FlagClient
): Promise<() => void> {
